import {keysRegistry} from './keys-research-registry.js';
import {armRegistry} from './arm-research-registry.js';
import {sndkRegistry} from './sndk-research-registry.js';
import {mrvlRegistry} from './mrvl-research-registry.js';
// Versioned company packages are independent; earlier files stay byte-identical.
import {incrementalRegistry} from './incremental-research-registry.js';
import {amatRegistry} from './amat-research-registry.js';
import {lrcxRegistry} from './lrcx-research-registry.js';
import {asmlRegistry} from './asml-research-registry.js';
import {fnRegistry} from './fn-research-registry.js';
import {cdnsRegistry} from './cdns-research-registry.js';
import {snpsRegistry} from './snps-research-registry.js';
import {ontoRegistry} from './onto-research-registry.js';
import {crdoRegistry} from './crdo-research-registry.js';
import {camtRegistry} from './camt-research-registry.js';
import {nvmiRegistry} from './nvmi-research-registry.js';
import {amdRegistry} from './amd-research-registry.js';
export {incrementalRegistry};
export const incrementalPackages=Object.freeze([incrementalRegistry,amatRegistry,lrcxRegistry,asmlRegistry,fnRegistry,cdnsRegistry,snpsRegistry,nvmiRegistry,ontoRegistry,camtRegistry,mrvlRegistry,amdRegistry,crdoRegistry,sndkRegistry,armRegistry,keysRegistry]);
